export function graphemeLow(codeUnit: number): number {
  return data.charCodeAt(start.charCodeAt(codeUnit >> 5) + (codeUnit & 31));
}
export function graphemeHigh(lead: number, tail: number): number {
  return data.charCodeAt(start.charCodeAt(2048 + (tail >> 8) + (lead << 2)) + (tail & 255));
}
export function graphemeMove(state: number, category: number): number {
  return stateMachine.charCodeAt((state & -4) + category);
}
